-- Flyboard clean-room PostgreSQL schema
CREATE TABLE IF NOT EXISTS admins(id bigserial PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,role text NOT NULL CHECK(role IN('owner','operator','auditor')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bootstrap_tokens(digest bytea PRIMARY KEY,used_at timestamptz);
CREATE TABLE IF NOT EXISTS admin_sessions(token_digest bytea PRIMARY KEY,admin_id bigint NOT NULL REFERENCES admins ON DELETE CASCADE,csrf_token text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY,email text NOT NULL UNIQUE,token_digest bytea UNIQUE,banned boolean NOT NULL DEFAULT false,expires_at timestamptz,device_limit integer NOT NULL DEFAULT 0 CHECK(device_limit>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS upstreams(id bigserial PRIMARY KEY,name text NOT NULL,email text,subscribe_url_ciphertext bytea NOT NULL,credentials_ciphertext bytea,enabled boolean NOT NULL DEFAULT true,upload bigint NOT NULL DEFAULT 0,download bigint NOT NULL DEFAULT 0,transfer_enable bigint NOT NULL DEFAULT 0,expires_at timestamptz,last_node_count integer NOT NULL DEFAULT 0,last_pulled_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS upstream_nodes(id bigserial PRIMARY KEY,upstream_id bigint NOT NULL REFERENCES upstreams ON DELETE CASCADE,name text NOT NULL,type varchar(32) NOT NULL,address text NOT NULL,port integer CHECK(port between 1 and 65535),config jsonb NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS upstream_nodes_enabled ON upstream_nodes(upstream_id,enabled);
CREATE TABLE IF NOT EXISTS clients(id bigserial PRIMARY KEY,name text NOT NULL,token_digest bytea NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT true,expires_at timestamptz,traffic_limit bigint NOT NULL DEFAULT 0,traffic_used bigint NOT NULL DEFAULT 0,device_limit integer NOT NULL DEFAULT 0,device_window integer NOT NULL DEFAULT 120 CHECK(device_window between 60 and 2592000),access_count bigint NOT NULL DEFAULT 0,last_access_at timestamptz,note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS nodes(id bigserial PRIMARY KEY,name text NOT NULL UNIQUE,address text,enabled boolean NOT NULL DEFAULT true,token_digest bytea UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS access_logs(id bigserial PRIMARY KEY,user_id bigint REFERENCES users ON DELETE SET NULL,client_id bigint REFERENCES clients ON DELETE SET NULL,ip inet,user_agent text,fingerprint bytea,action text NOT NULL,reason text,path text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS upstream_pull_executions(id bigserial PRIMARY KEY,upstream_id bigint NOT NULL REFERENCES upstreams ON DELETE CASCADE,status text NOT NULL CHECK(status IN('pending','running','completed','error')),error_code text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz); CREATE UNIQUE INDEX IF NOT EXISTS one_active_pull ON upstream_pull_executions(upstream_id) WHERE status IN('pending','running');
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value jsonb NOT NULL,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_outbox(id bigserial PRIMARY KEY,aggregate_type text NOT NULL,aggregate_id bigint NOT NULL,revision bigint NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz);
ALTER TABLE upstream_nodes ADD COLUMN IF NOT EXISTS raw_uri text;
ALTER TABLE upstream_pull_executions ADD COLUMN IF NOT EXISTS heartbeat_at timestamptz;
ALTER TABLE upstream_pull_executions ADD COLUMN IF NOT EXISTS deadline_at timestamptz NOT NULL DEFAULT (now()+interval '10 minutes');
